Para implementar un decorador que acepte parámetros, necesitamos tres niveles de funciones: la función principal que recibe los parámetros del decorador, la función decoradora que recibe la función original, y la función envolvente (*wrapper*) que contiene la lógica de reintento.

Aquí tienes la implementación siguiendo las mejores prácticas de Python:

```python
import time
from functools import wraps

def retry(max_attempts: int, delay: float, exceptions: tuple):
    """
    Decorador para reintentar una función en caso de excepciones específicas.

    :param max_attempts: Número máximo de intentos totales.
    :param delay: Segundos de espera entre reintentos.
    :param exceptions: Tupla de tipos de excepción que deben disparar el reintento.
    """
    def decorator(func):
        @wraps(func)  # Preserva los metadatos de la función original (nombre, docstring, etc.)
        def wrapper(*args, **kwargs):
            last_exception = None

            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    # Si no es el último intento, esperamos antes de reintentar
                    if attempt < max_attempts:
                        print(f"⚠️ Intento {attempt}/{max_attempts} falló ({type(e).__name__}). "
                              f"Reintentando en {delay}s...")
                        time.sleep(delay)
                    else:
                        print(f"❌ Se agotaron los {max_attempts} intentos.")
                except Exception as e:
                    # Si la excepción no está en la tupla permitida, la lanzamos de inmediato
                    raise e

            # Si el bucle termina sin éxito, relanzamos la última excepción capturada
            if last_exception:
                raise last_exception

        return wrapper
    return decorator

# --- Pruebas de uso ---

# 1. Caso de éxito tras un fallo
counter = 0

@retry(max_attempts=3, delay=1.0, exceptions=(IOError, TimeoutError))
def fetch_data(url):
    global counter
    counter += 1
    if counter < 3:
        print(f"Simulando error en intento {counter}...")
        raise IOError("Error de conexión simulado")
    return {"data": "success", "url": url}

# 2. Caso de fallo total
@retry(max_attempts=2, delay=0.5, exceptions=(ValueError,))
def fail_permanently():
    print("Ejecutando función que siempre falla...")
    raise ValueError("Error fatal de valor")

if __name__ == "__main__":
    print("--- Test 1: Éxito tras reintentos ---")
    try:
        result = fetch_data("https://api.example.com")
        print(f"Resultado final: {result}")
    except Exception as e:
        print(f"Error inesperado: {e}")

    print("\n--- Test 2: Agotamiento de intentos ---")
    try:
        fail_permanently()
    except ValueError as e:
        print(f"Capturado error final: {e}")

    print("\n--- Test 3: Excepción no permitida (debe fallar de inmediato) ---")
    @retry(max_attempts=5, delay=1.0, exceptions=(IOError,))
    def unexpected_error():
        raise TypeError("Este error no está en la lista de reintentos")

    try:
        unexpected_error()
    except TypeError as e:
        print(f"Capturado error no permitido: {e}")
